sp_widget.client_script:
api.controller = function($scope, $timeout) {
  $timeout(function() {
    var steps = document.querySelectorAll('.gn-step-item');
    var dots  = document.querySelectorAll('.gn-sdot');

    function setActive(index) {
      steps.forEach(function(s, i) {
        s.classList.toggle('gn-step--active', i === index);
      });
      dots.forEach(function(d, i) {
        d.classList.toggle('gn-sdot--active', i === index);
      });
    }

    setActive(0);

    steps.forEach(function(step) {
      step.addEventListener('click', function() {
        setActive(parseInt(step.getAttribute('data-index')));
      });
    });

    if ('IntersectionObserver' in window) {
      var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
          if (entry.isIntersecting) {
            setActive(parseInt(entry.target.getAttribute('data-index')));
          }
        });
      }, { rootMargin: '-40% 0px -40% 0px', threshold: 0 });
      steps.forEach(function(s) { observer.observe(s); });
    }

  }, 300);
};

sp_widget.css:
/* ─── Reset ───────────────────────────────────────────── */
.gn-steps-wrapper *,
.gn-steps-wrapper *::before,
.gn-steps-wrapper *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ─── Outer wrapper ───────────────────────────────────── */
.gn-steps-wrapper {
  font-family: 'Inter', 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  background: #f9f9fb;
  width: 100%;
  padding: 64px 0;
}

/* ─── 3-column layout ─────────────────────────────────── */
.gn-steps-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 60px;
  display: grid;
  grid-template-columns: 280px 180px 1fr;
  align-items: center;
  gap: 0 40px;
}

/* ─── COL 1: Eyebrow + Heading ────────────────────────── */
.gn-steps-left {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-self: center;
}

.gn-steps-eyebrow {
  font-size: 13px;
  font-weight: 500;
  color: #5443ad;
  letter-spacing: 0.01em;
}

.gn-steps-heading {
  font-size: 24px;
  font-weight: 400;
  line-height: 1.35;
  color: #111827;
}

/* ─── COL 2: 2×2 Dot grid ─────────────────────────────── */
.gn-steps-dots {
  display: grid;
  grid-template-columns: repeat(2, 72px);
  grid-template-rows: repeat(2, 72px);
  gap: 14px;
  align-self: center;
  justify-self: center;
}

.gn-sdot {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: #e2e2e8;
  display: block;
  transition: background 0.3s ease, transform 0.3s ease;
}

.gn-sdot--active {
  background: #5443ad;
  transform: scale(1.05);
}

/* ─── COL 3: Steps list ───────────────────────────────── */
.gn-steps-right {
  display: flex;
  flex-direction: column;
  align-self: stretch;
  justify-content: center;
}

/* ─── Each step row ───────────────────────────────────── */
.gn-step-item {
  display: grid;
  grid-template-columns: 32px 180px 1fr;
  align-items: center;
  gap: 0 20px;
  padding: 18px 0;
  border-bottom: 1px solid #ebebeb;
  cursor: pointer;
}

.gn-step-item:first-child {
  border-top: 1px solid #ebebeb;
}

/* Number */
.gn-step-num {
  font-size: 14px;
  font-weight: 500;
  color: #adb5bd;
  transition: color 0.25s;
}

/* Title */
.gn-step-title {
  font-size: 14px;
  font-weight: 600;
  color: #1f2937;
  transition: color 0.25s;
}

/* Description */
.gn-step-desc {
  font-size: 14px;
  font-weight: 400;
  color: #9ca3af;
  transition: color 0.25s;
}

/* ─── Active state ────────────────────────────────────── */
.gn-step-item.gn-step--active .gn-step-num {
  color: #5443ad;
  font-weight: 600;
}

.gn-step-item.gn-step--active .gn-step-title {
  color: #5443ad;
}

.gn-step-item.gn-step--active .gn-step-desc {
  color: #8a7fc4;
}

/* ─── Responsive ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .gn-steps-inner {
    grid-template-columns: 220px 160px 1fr;
    gap: 0 28px;
    padding: 0 40px;
  }
  .gn-steps-dots {
    grid-template-columns: repeat(2, 60px);
    grid-template-rows: repeat(2, 60px);
    gap: 12px;
  }
  .gn-sdot { width: 60px; height: 60px; }
}

@media (max-width: 820px) {
  .gn-steps-inner {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto;
    gap: 32px 0;
    padding: 0 32px;
  }
  .gn-steps-dots {
    grid-template-columns: repeat(2, 56px);
    grid-template-rows: repeat(2, 56px);
    justify-self: start;
    gap: 12px;
  }
  .gn-sdot { width: 56px; height: 56px; }
  .gn-step-item { grid-template-columns: 28px 140px 1fr; }
}

@media (max-width: 520px) {
  .gn-steps-wrapper { padding: 40px 0; }
  .gn-steps-inner   { padding: 0 20px; gap: 24px 0; }
  .gn-steps-heading { font-size: 20px; }
  .gn-step-item     { grid-template-columns: 28px 1fr; }
  .gn-step-desc     { display: none; }
  .gn-steps-dots {
    grid-template-columns: repeat(2, 48px);
    grid-template-rows: repeat(2, 48px);
  }
  .gn-sdot { width: 48px; height: 48px; }
}
